//! Snapshot-bound partial index changes; patch bytes are generated by Git, never the UI.
use super::*;

fn blocked(message: &str) -> AppError {
    AppError::new("hunk_unsupported", message)
}
fn split_patch(diff: &str) -> Result<(&str, Vec<&str>)> {
    if !diff.ends_with('\n')
        || diff.matches("diff --git ").count() != 1
        || diff.lines().any(|line| {
            line.starts_with("new file mode ")
                || line.starts_with("deleted file mode ")
                || line.starts_with("old mode ")
                || line.starts_with("new mode ")
                || line.starts_with("Binary files ")
                || line.starts_with("GIT binary patch")
        })
    {
        return Err(blocked("Hunks require a complete text modification with unchanged file mode. Use Stage or Unstage file for new, deleted, binary or mode-changing files."));
    }
    let starts = diff
        .match_indices("\n@@ ")
        .map(|(i, _)| i + 1)
        .collect::<Vec<_>>();
    let first = *starts
        .first()
        .ok_or_else(|| blocked("This file has no supported text hunks."))?;
    if starts.len() > 1000 {
        return Err(blocked("This file exceeds the 1,000-hunk review budget."));
    }
    let hunks = starts
        .iter()
        .enumerate()
        .map(|(i, start)| &diff[*start..starts.get(i + 1).copied().unwrap_or(diff.len())])
        .collect();
    Ok((&diff[..first], hunks))
}
impl GitCli {
    pub fn preview_hunks(
        &self,
        root: &Path,
        file: &NativePath,
        staged: bool,
    ) -> Result<HunkPreview> {
        self.registered_change(root, file, staged)?;
        let before = self.preview_token(root, file, staged)?;
        let path = relative(file)?;
        let attributes = self
            .read(
                root,
                &[
                    "check-attr".as_ref(),
                    "-z".as_ref(),
                    "filter".as_ref(),
                    "--".as_ref(),
                    path.as_os_str(),
                ],
                65536,
            )?
            .bytes;
        let values = attributes
            .split(|b| *b == 0)
            .filter(|b| !b.is_empty())
            .collect::<Vec<_>>();
        if values.len() != 3 || !matches!(values[2], b"unspecified" | b"unset") {
            return Err(blocked("Configured clean filters require whole-file staging; partial staging is unavailable for this file."));
        }
        // Only regular tracked files: no symlinks, gitlinks, intent-to-add or rename metadata.
        if let Ok(meta) = fs::symlink_metadata(root.join(&path)) {
            if !meta.file_type().is_file() {
                return Err(blocked("Hunks are available only for regular text files."));
            }
        }
        let index = self
            .read(
                root,
                &[
                    "ls-files".as_ref(),
                    "--stage".as_ref(),
                    "-z".as_ref(),
                    "--".as_ref(),
                    path.as_os_str(),
                ],
                65536,
            )?
            .bytes;
        if !(index.starts_with(b"100644 ") || index.starts_with(b"100755 "))
            || index.iter().filter(|b| **b == 0).count() != 1
        {
            return Err(blocked(
                "Hunks are available only for tracked, unconflicted regular files.",
            ));
        }
        let mut args = vec![
            "diff".as_ref(),
            "--no-ext-diff".as_ref(),
            "--no-textconv".as_ref(),
            "--no-renames".as_ref(),
            "--no-color".as_ref(),
            "--no-relative".as_ref(),
            "--full-index".as_ref(),
            "--src-prefix=a/".as_ref(),
            "--dst-prefix=b/".as_ref(),
            "--unified=3".as_ref(),
            "--inter-hunk-context=0".as_ref(),
            "--diff-algorithm=myers".as_ref(),
            "--no-indent-heuristic".as_ref(),
        ];
        if staged {
            args.push("--cached".as_ref());
        }
        args.extend(["--".as_ref(), path.as_os_str()]);
        let out = self.execute(root, &args, PATCH_LIMIT, true)?;
        if out.truncated {
            return Err(blocked(
                "The complete patch exceeds the hunk review budget. Use file staging.",
            ));
        }
        let diff = String::from_utf8(out.bytes).map_err(|_| {
            blocked("Hunks require valid UTF-8 text. Use file staging for this encoding.")
        })?;
        let (_, parts) = split_patch(&diff)?;
        let headers = parts
            .iter()
            .map(|h| h.lines().next().unwrap_or_default().to_owned())
            .collect::<Vec<_>>();
        let config = self.config_snapshot(root)?;
        let attributes = crate::merge::scratch::attributes(self, root)?;
        let token = digest(
            &serde_json::to_vec(&(&before, &diff, &config, &attributes))
                .map_err(|e| AppError::new("snapshot", e.to_string()))?,
        );
        if self.preview_token(root, file, staged)? != before {
            return Err(AppError::new(
                "stale_preview",
                "File or index changed. Review hunks again.",
            ));
        }
        Ok(HunkPreview {
            file: FilePreview {
                path: file.clone(),
                staged,
                token: before,
                diff,
                truncated: false,
            },
            headers,
            token,
        })
    }
    pub fn change_hunk(
        &self,
        root: &Path,
        file: &NativePath,
        staged: bool,
        hunk: usize,
        token: &str,
    ) -> Result<()> {
        let p = self.preview_hunks(root, file, staged)?;
        if p.token != token {
            return Err(AppError::new(
                "stale_preview",
                "File, configuration or index changed. Review hunks again.",
            ));
        }
        let (header, parts) = split_patch(&p.file.diff)?;
        let part = parts
            .get(hunk)
            .ok_or_else(|| blocked("Choose a hunk from the current complete patch."))?;
        let patch = format!("{header}{part}");
        let (d, state) = self.write_state(root)?;
        let mut lock = OperationLock::acquire(d.git_dir.join("index.lock"))?;
        let original = index_bytes(&d.git_dir)?;
        let temporary = tempfile::NamedTempFile::new_in(&d.git_dir)?.into_temp_path();
        fs::write(&temporary, &original)?;
        preserve_index_timestamp(&d.git_dir.join("index"), &temporary)?;
        if self.preview_hunks(root, file, staged)?.token != token {
            return Err(AppError::new(
                "stale_preview",
                "Hunk changed while acquiring the index lock. Review again.",
            ));
        }
        let mut args = vec![
            "apply".into(),
            "--cached".into(),
            "--whitespace=nowarn".into(),
        ];
        if staged {
            args.push("--reverse".into());
        }
        // Apply to a private index, then atomically publish only after full revalidation.
        run_git_write(
            root,
            &args,
            Some(temporary.as_ref()),
            None,
            Some(patch.as_bytes()),
        )?;
        if self.write_state(root)?.1 != state
            || self.preview_hunks(root, file, staged)?.token != token
        {
            return Err(AppError::new(
                "stale_preview",
                "Hunk changed during preparation. Original index preserved; review again.",
            ));
        }
        let bytes = read_bounded(&temporary, INDEX_LIMIT)?;
        lock.publish(
            &d.git_dir.join("index"),
            &bytes,
            Some(fs::metadata(&temporary)?.modified()?),
        )
    }
}
